const $=id=>document.getElementById(id);
let store,ui={monsterId:'',profileId:'normal-f2p',partySize:1,partyDps:[],damageMode:'direct',encounterOverhead:0,physicalMitigation:0,magicalMitigation:0,minimumWindow:0,farmMode:'theoretical',farmDps:0,manualKpm:10,spawnModel:'uncapped',spawnCapacity:0,farmingUptime:null,aoeEnabled:false,aoeTargets:3,groupingSeconds:1,castingInterval:2,bossOps:{travel:60,respawn:3600,competition:.5,eligible:1,share:.2},testMaxHit:0,testBurst3:0,testBurst5:0,testBurst10:0},pending=null;
async function boot(){try{const a=await Promise.all(['aos-monsters-full.json','monster-balance-proposed.json','default-progression-config.json'].map(f=>fetch('./public/data/'+f).then(r=>{if(!r.ok)throw Error('Cannot load '+f);return r.json()})));const [original,proposal,cf]=a;validateData(original);store=createStore({original,proposal,config:{...DEFAULT_CONFIG,...cf,powerCurve:structuredClone(POWER_CURVE),brackets:structuredClone(TARGET_BRACKETS),baseTargetHours:302.4}});bind();nav();await store.loadPersisted();if(!Array.isArray(store.getState().config.appliedExpTable)){store.getState().config.appliedExpTable=generateBaseTable(store.activeMonsters(),store.getState().config).rows.map(x=>x.requiredExp);store.persist()}store.subscribe(render);render()}catch(e){$('content').innerHTML='<section class="panel"><h2>Workbench could not load source data</h2><p>'+esc(e.message||e)+'</p><p>Serve this folder with a local static web server. No backend is required.</p></section>'}}
function validateData(d){if(!Array.isArray(d?.monsters))throw Error('Source JSON has no monsters array.');if(new Set(d.monsters.map(x=>String(x.id))).size!==d.monsters.length)throw Error('Duplicate source Monster IDs.')}
function nav(){$('navigation').innerHTML=NAVIGATION.map(g=>'<div class="nav-group"><h3>'+g[0]+'</h3>'+g[1].map(x=>'<button class="nav-item" data-page="'+x[0]+'"><span class="nav-icon">'+x[2]+'</span><span>'+x[1]+'</span></button>').join('')+'</div>').join('')}
function context(){const s=store.getState(),config={...DEFAULT_CONFIG,...s.config},monsters=store.activeMonsters(),recommended=generateBaseTable(monsters,config),base=Array.isArray(config.appliedExpTable)?generateBaseTable(monsters,{...config,expOverrides:config.appliedExpTable}):recommended,recommendedRewards=new Map();for(const r of base.rows){if(r.effectiveMonsterExp>0&&r.targetHours>0){const id=String(r.referenceMonsterId),v=r.requiredExp/(r.targetHours*(r.maximumExpPerHour/r.effectiveMonsterExp)),a=recommendedRewards.get(id)||[];a.push(v);recommendedRewards.set(id,a)}}for(const [id,a] of recommendedRewards)recommendedRewards.set(id,a.reduce((x,y)=>x+y,0)/a.length);const jobs=generateJobTables(monsters,base,config),scenarios=simulatePlayers(base,jobs,config),validation=validateBalance({original:s.original,monsters,base,jobs,scenarios,config,custom:s.custom,proposal:s.proposal.records,profiles:s.profiles.combat});return{store,ui,original:s.original,proposal:s.proposal,monsters,config,base,recommendedBase:recommended,recommendedRewards,jobs,scenarios,validation}}
function render(){if(!store)return;const s=store.getState(),c=context(),page=s.currentView||'dashboard';document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('page-title').textContent=PAGE_NAMES[page]||'Dashboard';$('breadcrumb').textContent=(NAVIGATION.find(g=>g[1].some(x=>x[0]===page))||['Overview'])[0]+' / '+(PAGE_NAMES[page]||'Dashboard');$('dataset-mode').value=s.mode;$('sync-mode').value=c.config.syncMode;$('project-name').textContent=s.project.name;$('save-state').textContent='Saved locally · '+s.project.versionName;const fail=c.validation.some(x=>x.status==='FAIL'),warn=c.validation.some(x=>x.status==='WARNING');$('validation-pill').textContent=fail?'Validation · FAIL':warn?'Validation · review':'Validation · PASS';$('validation-pill').style.color=fail?'var(--red)':warn?'var(--amber)':'var(--teal)';$('source-notice').hidden=false;$('source-notice').textContent='Loaded: original monster JSON, Monster Balance Master v2, MVP HP handoff, EXP Tool v2 and AOS UI handoff v2.4. Named ZIP and UI handoff v2.2 are absent from this workspace.';let html;if(page==='dashboard')html=renderDashboard(c);else if(['normal','mvp','abyss','database'].includes(page))html=renderMonsters(c,page==='database'?'all':page);else if(['power','profiles','ttk','stress','impact','impact-analysis'].includes(page))html=renderCombat(c,page);else if(['rewards','farming','maps','boss-rewards','gold'].includes(page))html=renderEconomy(c,page);else if(['base-exp','class1-exp','class2-exp','multi-client','comparison','battlepass'].includes(page))html=renderProgression(c,page);else html=renderAdmin(c,page);const f=document.activeElement?.dataset?.filter,pos=f?document.activeElement.selectionStart:null;$('content').innerHTML=html;if(f){const x=$('content').querySelector('[data-filter="'+f+'"]');if(x){x.focus();try{x.setSelectionRange(pos,pos)}catch{}}}}
function bind(){document.addEventListener('click',click);document.addEventListener('change',change);document.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-filter]')){store.getState().filters[t.dataset.filter]=t.type==='number'?Number(t.value):t.value;store.getState().tablePage=0;render()}});$('dialog-close').onclick=closeDialog;$('menu-toggle').onclick=()=>$('sidebar').classList.toggle('open');window.addEventListener('resize',render)}
function click(e){const n=e.target.closest('[data-page]');if(n){store.setView(n.dataset.page);$('sidebar').classList.remove('open');return}if(e.target.closest('[data-dialog-close]')){closeDialog();return}const ex=e.target.closest('[data-export]');if(ex){exportNamed(ex.dataset.export);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,c=context(),s=store.getState();if(a==='undo'){store.undo();return}if(a==='redo'){store.redo();return}if(a==='reset-config'){store.resetConfig({...structuredClone(DEFAULT_CONFIG),appliedExpTable:c.recommendedBase.rows.map(x=>x.requiredExp)});return}if(a==='save-version'||a==='duplicate-current'){const name=prompt('Version name',a==='save-version'?'Design Draft':'Design Draft Copy');if(name)store.saveVersion(name);return}if(a==='load-version'){store.loadVersion(b.dataset.version);return}if(a==='compare-version'){const v=s.versions.find(x=>x.project.versionId===b.dataset.version);dialog('Version comparison','<p>Current: '+esc(s.project.versionName)+'<br>Saved: '+esc(v?.project.versionName||'—')+'</p><p>Source versions: '+esc(s.project.sourceVersion||'—')+' / '+esc(v?.project.sourceVersion||'—')+'</p>');return}if(a==='monster-detail'){detail(c.monsters.find(m=>String(m.id)===b.dataset.id),c);return}if(a==='page-prev'){s.tablePage=Math.max(0,s.tablePage-1);render();return}if(a==='page-next'){s.tablePage++;render();return}
if(a==='bulk-adjust'){const ids=filtered(c),st=$('stat-choice')?.value,path=({hp:'stats.hp',mp:'stats.mp',atk:'stats.atk',matk:'stats.matk',def:'stats.def',mdef:'stats.mdef',baseExp:'rewards.baseExp',jobExp:'rewards.jobExp',goldMin:'rewards.goldMin',goldMax:'rewards.goldMax',level:'level'})[st];pending={type:'bulk',ids,path,op:$('bulk-operation').value,amount:Number($('bulk-amount').value)};dialog('Preview bulk adjustment','<p>'+ids.length+' records · '+pending.op+' '+pending.amount+' · '+esc(st)+'</p><p>'+ids.slice(0,5).map(id=>{const m=c.monsters.find(x=>String(x.id)===id),v=get(m,path),z=pending.op==='percent'?v*(1+pending.amount/100):v+pending.amount;return esc(m.name)+': '+fmt(v,2)+' → '+fmt(z,2)}).join('<br>')+'</p><div class="sticky-actions"><button class="button" data-dialog-close>Cancel</button><button class="button primary" data-action="apply-bulk">Apply preview</button></div>');return}
if(a==='apply-bulk'&&pending){store.bulkEdit(pending.ids,pending.path,pending.op,pending.amount);pending=null;closeDialog();return}if(a==='reset-filtered'){pending={type:'reset',ids:filtered(c)};dialog('Preview custom reset','<p>Remove custom overrides from '+pending.ids.length+' filtered records. Proposed values are retained.</p><div class="sticky-actions"><button class="button" data-dialog-close>Cancel</button><button class="button danger" data-action="apply-reset">Reset custom values</button></div>');return}if(a==='apply-reset'&&pending?.type==='reset'){pending.ids.forEach(id=>delete store.getState().custom[id]);store.record('Reset custom overrides for '+pending.ids.length+' records');store.getState().tablePage=0;store.emit();pending=null;closeDialog();return}if(a==='restore-original'){if(confirm('Switch to Original mode and remove Custom overrides?'))store.restoreOriginal();return}
if(a==='preview-rewards'){const patches={};for(const [id,value]of c.recommendedRewards)patches[id]={rewards:{baseExp:Math.max(0,Math.round(value))}};pending={type:'rewards',patches};dialog('Preview recommended monster rewards',Object.keys(patches).length+' normal monster records · Base EXP only. Job EXP, Gold and drops are unchanged until separately reviewed.<p>Sample changes:</p>'+Object.entries(patches).slice(0,8).map(([id,p])=>{const m=c.monsters.find(x=>String(x.id)===id);return m.name+': '+fmt(m.rewards.baseExp,0)+' → '+fmt(p.rewards.baseExp,0)}).join('<br>')+'<div class="sticky-actions"><button class="button" data-dialog-close>Cancel</button><button class="button primary" data-action="apply-rewards">Apply preview</button></div>');return}if(a==='apply-rewards'&&pending?.type==='rewards'){store.applyCustomPatches(pending.patches,'Applied recommended monster Base EXP');pending=null;closeDialog();return}if(a==='auto-rebalance'){s.rebalancePreview=autoRebalance(c.base,c.config);store.emit();return}if(a==='apply-rebalance'){const r=s.rebalancePreview;if(r?.feasible){store.updateConfig('appliedExpTable',r.recommended.map(x=>x.requiredExp));s.rebalancePreview=null;store.record('Applied previewed Base EXP table');store.emit()}return}
if(a.startsWith('export-')){exportNamed(exportName(a));return}if(a==='export-config'){exportNamed('aos-progression-config.json');return}if(a==='export-current-csv'){exportNamed('aos-normal-monster-balance.csv');return}if(a==='export-project'){exportNamed('aos-balance-project.json');return}if(a==='export-handoff'){exportNamed('aos-balance-handoff.html');return}if(a.startsWith('import-')){$('import-file').dataset.importType=a;$('import-file').click();return}
if(a==='reverse-hp'){const m=c.monsters.find(x=>String(x.id)===String(ui.monsterId))||c.monsters[0],p=s.profiles.combat.find(x=>x.id===ui.profileId)||s.profiles.combat[0],sec=Number($('reverse-target')?.value||60),hp=recommendedHp(sec,Number(p.effectiveDps||0));pending={type:'hp',id:String(m.id),hp};dialog('Reverse HP recommendation preview','<p>'+esc(m.name)+' · '+fmt(sec,1)+' sec × '+fmt(p.effectiveDps,0)+' DPS.</p><p>Current '+fmt(m.stats.hp,0)+' HP → proposed '+fmt(hp,0)+' HP</p><p>No data changes until Apply.</p><div class="sticky-actions"><button class="button" data-dialog-close>Cancel</button><button class="button primary" data-action="apply-reverse-hp">Apply proposed value</button></div>');return}if(a==='apply-reverse-hp'&&pending?.type==='hp'){store.edit(pending.id,['stats','hp'],pending.hp);pending=null;closeDialog();return}
if(a==='reset-power'){store.updateConfig('powerCurve',structuredClone(POWER_CURVE));return}if(a==='reset-brackets'){store.updateConfig('brackets',structuredClone(TARGET_BRACKETS));return}if(a==='add-profile'){s.profiles.combat.push({id:'custom-'+crypto.randomUUID(),name:'Custom Profile',type:'Custom',effectiveDps:0,maxHit:0,burst3:0,burst5:0,burst10:0,damageUptime:1,source:'Designer configured'});store.record('Added custom profile');store.emit();return}if(a==='duplicate-profile'){const p=structuredClone(s.profiles.combat[Number(b.dataset.index)]);p.id='custom-'+crypto.randomUUID();p.name+=' Copy';s.profiles.combat.push(p);store.record('Duplicated combat profile');store.emit();return}if(a==='delete-profile'){s.profiles.combat.splice(Number(b.dataset.index),1);store.record('Removed combat profile');store.emit();return}}
function change(e){const t=e.target;if(!store)return;if(t.id==='dataset-mode'){store.setMode(t.value);return}if(t.id==='sync-mode'){store.updateConfig('syncMode',t.value);return}if(t.id==='stat-choice'){setMonsterStat(t.value);render();return}if(t.matches('[data-edit]')){const v=t.type==='number'?Number(t.value):t.value;if(t.type==='number'&&!Number.isFinite(v))return;store.edit(t.dataset.id,t.dataset.edit.split('.'),v);return}if(t.matches('[data-config]')){let v=t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value):t.value;const key=t.dataset.config;if(key==='expBoostUptime'||key==='farmingUptime')v/=100;if(key==='manualMode'||key==='explicitPartyMode')v=v==='true'||v===true;if(key==='partyShares')v=String(v).split(',').map(Number).filter(Number.isFinite);if(key==='lockedLevels')v=String(v).split(',').map(Number).filter(Number.isInteger);if(key==='balancePreset'&&v!=='custom'){store.updateConfig('balancePreset',v);store.updateConfig('multiClientEfficiency',({controlled:1.5,balanced:2,unrestricted:3})[v]);store.updateConfig('expMultiplier',2.1);return}if(t.type==='number'&&!Number.isFinite(v))return;if(key==='multiClientEfficiency'){const preset=store.getState().config.balancePreset,expected=({controlled:1.5,balanced:2,unrestricted:3})[preset];if(expected!==v)store.updateConfig('balancePreset','custom')}store.updateConfig(key,v);return}if(t.matches('[data-ttk-index]')){const a=structuredClone(store.getState().config.normalTtkTargets);a[Number(t.dataset.ttkIndex)][t.dataset.ttkKey]=t.value;store.updateConfig('normalTtkTargets',a);return}if(t.matches('[data-power-index]')){const a=structuredClone(store.getState().config.powerCurve);a[Number(t.dataset.powerIndex)][t.dataset.powerKey]=Number(t.value);store.updateConfig('powerCurve',a);return}if(t.matches('[data-profile-index]')){const p=store.getState().profiles.combat[Number(t.dataset.profileIndex)],k=t.dataset.profileKey;p[k]=t.type==='number'?Number(t.value):t.value;store.record('Combat profile updated: '+p.name);store.emit();return}if(t.matches('[data-job-milestone-index]')){const a=structuredClone(store.getState().config.milestones.class2);a[Number(t.dataset.jobMilestoneIndex)][t.dataset.jobMilestoneKey]=Number(t.value);store.updateConfig('milestones.class2',a);return}if(t.matches('[data-bracket-index]')){const a=structuredClone(store.getState().config.brackets);a[Number(t.dataset.bracketIndex)].hours=Number(t.value);store.updateConfig('brackets',a);return}if(t.matches('[data-ui]')){let v=t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value):t.value;if(t.dataset.ui==='farmingUptime')v/=100;if(t.dataset.ui==='partySize'){v=Math.max(1,Math.min(5,v));const p=store.getState().profiles.combat.find(x=>x.id===ui.profileId)||store.getState().profiles.combat[0];ui.partyDps=Array.from({length:v},(_,i)=>ui.partyDps[i]??Number(p.effectiveDps||0))}ui[t.dataset.ui]=v;render();return}if(t.matches('[data-party-dps]')){ui.partyDps[Number(t.dataset.partyDps)]=Number(t.value);render();return}if(t.matches('[data-bossop]')){const k=t.dataset.bossop;ui.bossOps[k]=Number(t.value)/(k==='travel'||k==='respawn'?1:100);render();return}if(t.matches('[data-roadmap]')){const a=structuredClone(store.getState().config.roadmap||[]);a[Number(t.dataset.roadmap)]=t.value;store.updateConfig('roadmap',a);return}if(t.id==='import-file'&&t.files?.[0])importFile(t.files[0],t.dataset.importType)}
async function importFile(file,type){try{const text=await file.text();if(type==='import-telemetry'){const rows=parseCsv(text),summary=summarize(rows);store.importTelemetry(rows,summary);dialog('Telemetry imported',rows.length+' rows parsed · labeled Measured');return}if(file.name.endsWith('.csv')){const records=parseOverrideCsv(parseCsv(text));if(!Object.keys(records).length)throw Error('No supported ID and balance columns found in CSV.');store.importProposal(records,file.name);dialog('CSV proposal imported safely',Object.keys(records).length+' Monster IDs parsed.');return}if(file.name.endsWith('.html')||/^\s*</.test(text)){const x=parseHtml(text,file.name);store.importProposal(x.records,x.source);dialog('HTML parsed safely',Object.keys(x.records).length+' records extracted; scripts were not executed.');return}const d=JSON.parse(text);if(type==='import-monsters'||d.monsters){validateMonster(d);store.importMonsterDataset(d);return}if(d.schemaVersion||d.config&&d.project){store.importProject(d);return}if(Array.isArray(d.records)){store.importProposal(d.records,file.name);return}throw Error('Unrecognized import file.')}catch(e){dialog('Import rejected',esc(e.message||e)+'<p>No changes were applied.</p>')}finally{$('import-file').value=''}}
function parseHtml(text,name){const records={};for(const k of ['normalData','bossData'])for(const r of extractArray(text,k)){const o={stats:{},attributes:{},rewards:{},metadata:{}};for(const f of ['hp','mp','atk','matk','def','mdef','range','interval'])if(r['new_'+f]!=null)o.stats[f]=r['new_'+f];for(const f of ['str','agi','vit','int','dex','luk'])if(r['new_'+f]!=null)o.attributes[f]=r['new_'+f];for(const f of ['baseExp','jobExp','goldMin','goldMax'])if(r['new_'+f]!=null)o.rewards[f]=r['new_'+f];for(const f of ['element','aggro','archetype','counterplay_axis','secondary_axis','proposed_skill','counterplay','tier','status'])if(r[f]!=null)o.metadata[f]=r[f];records[String(r.id)]=o}const re=/<tr><td>([^<]+)<\/td><td class="num new">([\d,]+)M<\/td>/g;let m;while((m=re.exec(text))){const mon=store.activeMonsters().find(x=>x.name.toLowerCase()===m[1].toLowerCase());if(mon)records[String(mon.id)]={...(records[String(mon.id)]||{}),stats:{...(records[String(mon.id)]?.stats||{}),hp:Number(m[2].replaceAll(',',''))*1e6}}}if(!Object.keys(records).length)throw Error('No supported balance arrays or boss HP table found.');return{records,source:name}}
function parseOverrideCsv(rows){const records={},maps={level:['level','newlevel','leveleffective'],hp:['hp','newhp','hpeffective'],mp:['mp','newmp','mpeffective'],atk:['atk','newatk','atkeffective'],matk:['matk','newmatk','matkeffective'],def:['def','newdef','defeffective'],mdef:['mdef','newmdef','mdefeffective'],range:['range','newrange','rangeeffective'],interval:['interval','newinterval','intervaleffective'],baseExp:['baseexp','newbaseexp','baseexpeffective'],jobExp:['jobexp','newjobexp','jobexpeffective'],goldMin:['goldmin','newgoldmin','goldmineffective'],goldMax:['goldmax','newgoldmax','goldmaxeffective']};for(const row of rows){const norm={};for(const [k,v]of Object.entries(row))norm[k.toLowerCase().replace(/[ _-]/g,'')]=v;const id=norm.id||norm.monsterid;if(!id)continue;const out={stats:{},rewards:{}};for(const [field,keys]of Object.entries(maps)){let v;for(const k of keys)if(norm[k]!=null&&norm[k]!==''){v=Number(norm[k]);if(Number.isFinite(v))break}if(v==null)continue;if(['baseExp','jobExp','goldMin','goldMax'].includes(field))out.rewards[field]=v;else if(field==='level')out.level=v;else out.stats[field]=v}if(Object.keys(out.stats).length||Object.keys(out.rewards).length||out.level!=null)records[String(id)]=out}return records}
function extractArray(s,n){const token='const '+n+'=',at=s.indexOf(token);if(at<0)return[];let i=at+token.length;while(/\s/.test(s[i]))i++;const start=i;let d=0,q='',escp=false;for(;i<s.length;i++){const c=s[i];if(q){if(escp)escp=false;else if(c==='\\')escp=true;else if(c===q)q='';continue}if(c==='"'||c==="'"){q=c;continue}if(c==='[')d++;else if(c===']'){d--;if(!d){i++;break}}}return JSON.parse(s.slice(start,i))}
function parseCsv(s){const lines=s.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(!lines.length)return[];const split=l=>{const a=[];let v='',q=false;for(let i=0;i<l.length;i++){const c=l[i];if(c==='"'&&l[i+1]==='"'&&q){v+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){a.push(v);v=''}else v+=c}a.push(v);return a};const h=split(lines[0]);return lines.slice(1).map(l=>Object.fromEntries(split(l).map((v,i)=>[h[i],v])))}
function summarize(rows){const keys=['combat_duration','effective_dps','damage_dealt','max_single_hit','burst_3s','burst_5s','burst_10s','movement_time','looting_time','kills','base_exp_earned','job_exp_earned','gold_earned','session_duration'],out={source:'Measured telemetry import',sampleSize:rows.length,metrics:{}};for(const k of keys){const a=rows.map(x=>Number(x[k])).filter(Number.isFinite).sort((x,y)=>x-y);if(a.length)out.metrics[k]={p10:quant(a,.1),p25:quant(a,.25),p50:quant(a,.5),p75:quant(a,.75),p90:quant(a,.9),p95:quant(a,.95),max:a.at(-1),sampleSize:a.length}}return out}
function quant(a,p){return a[Math.floor((a.length-1)*p)]}
function validateMonster(d){if(!Array.isArray(d?.monsters))throw Error('Monster JSON needs monsters[].');const ids=d.monsters.map(x=>String(x.id));if(new Set(ids).size!==ids.length||ids.includes('undefined'))throw Error('Monster IDs must be unique and present.');for(const m of d.monsters)if(!m.name||!Number.isFinite(Number(m.level))||!m.stats||!m.rewards)throw Error('Required field missing on Monster '+m.id)}
function filtered(c){const f=store.getState().filters,page=store.getState().currentView;return c.monsters.filter(m=>{if(page==='normal'&&m.boss)return false;if(page==='mvp'&&(!m.boss||m.metadata?.tier==='Abyss'))return false;if(page==='abyss'&&(!m.boss||m.metadata?.tier!=='Abyss'))return false;return(!f.search||String(m.name+' '+m.id).toLowerCase().includes(f.search.toLowerCase()))&&m.level>=Number(f.minLevel||1)&&m.level<=Number(f.maxLevel||999)&&(f.element==='all'||m.element===f.element)&&(f.race==='all'||m.race===f.race)&&(f.aggro==='all'||m.aggro===f.aggro)&&(f.map==='all'||(m.maps||[]).some(x=>x.name===f.map))&&(f.archetype==='all'||m.metadata?.archetype===f.archetype)}).map(m=>String(m.id))}
function get(o,p){return p.split('.').reduce((x,k)=>x?.[k],o)}
function detail(m,c){if(!m)return;const o=c.original.monsters.find(x=>String(x.id)===String(m.id)),p=store.getState().proposal.records[String(m.id)];dialog(m.name+' · Lv '+m.level,'<div class="keyval">'+[['ID',m.id],['Category',m.boss?'Boss':'Normal'],['Tier',m.metadata?.tier||'—'],['Race / Element',m.race+' / '+m.element],['Aggro',m.aggro],['Maps',(m.maps||[]).map(x=>x.name).join(', ')],['HP original',fmt(o.stats.hp,0)],['HP active',fmt(m.stats.hp,0)],['Base EXP',fmt(m.rewards.baseExp,0)],['Job EXP',fmt(m.rewards.jobExp,0)],['Archetype',m.metadata?.archetype||'—']].map(x=>'<div><small>'+esc(x[0])+'</small><b>'+esc(x[1])+'</b></div>').join('')+'</div><h3>Original rewards, full drops and overrides</h3><pre>'+esc(JSON.stringify({stats:o.stats,attributes:o.attributes,rewards:o.rewards,drops:o.drops,proposal:p||null,custom:store.getState().custom[String(m.id)]||null},null,2))+'</pre>')}
function dialog(t,h){$('dialog-title').textContent=t;$('dialog-body').innerHTML=h;const d=$('detail-dialog');if(!d.open)d.showModal()}function closeDialog(){$('detail-dialog').close()}
function exportName(a){return({'export-base-csv':'aos-base-exp-table.csv','export-base-json':'aos-base-exp-table.json','export-class1-csv':'aos-class1-job-exp-table.csv','export-class1-json':'aos-class1-job-exp-table.json','export-class2-csv':'aos-class2-job-exp-table.csv','export-class2-json':'aos-class2-job-exp-table.json','export-config':'aos-progression-config.json','export-project':'aos-balance-project.json','export-handoff':'aos-balance-handoff.html','export-current-csv':'aos-normal-monster-balance.csv'})[a]||a}
function exportNamed(name){
 const c=context(),s=store.getState(),meta={projectId:s.project.id,versionId:s.project.versionId,versionName:s.project.versionName,sourceVersion:s.project.sourceVersion,exportedAt:new Date().toISOString(),mode:s.mode,assumptions:{maxExpMultiplier:c.config.maxExpMultiplier,minimumModeledHours:c.config.minimumModeledHours,spawnModel:c.config.spawnModel,farmingUptime:c.config.farmingUptime}},orig=s.original;
 const jobs=k=>c.jobs[k].rows.map(r=>({...r,requiredExp:Math.round(r.requiredExp),cumulativeExp:Math.round(r.cumulativeExp)}));
 const base=c.base.rows.map(r=>({currentLevel:r.currentLevel,nextLevel:r.nextLevel,requiredExp:Math.round(r.requiredExp),cumulativeExp:Math.round(r.cumulativeExp),growthPct:r.growthPct,referenceMonster:r.referenceMonster,referenceMonsterId:r.referenceMonsterId,monsterLevelRange:r.monsterLevelRange,effectiveMonsterHp:r.effectiveMonsterHp,effectiveMonsterExp:r.effectiveMonsterExp,expectedTtkSeconds:r.expectedTtkSeconds,effectiveKillRate:r.effectiveKillRate,expectedKillsRequired:Math.round(r.requiredExp/Math.max(1,r.effectiveMonsterExp)),soloExpPerHour:r.soloExpPerHour,optimizedExpPerHour:r.optimizedExpPerHour,maximumExpPerHour:r.maximumExpPerHour,soloTimeHours:r.soloTimeHours,fastestTimeHours:r.fastestTimeHours,cumulativePlaytimeHours:r.cumulativePlaytimeHours,completionDay:r.completionDay,battlePassSeason:r.battlePassSeason}));
 const active=c.monsters,boss=active.filter(m=>m.boss),normal=active.filter(m=>!m.boss),effective={...structuredClone(orig),monsters:active},project={...store.exportProject(),originalSource:orig,proposal:s.proposal,activeEffective:effective},outputs={};
 outputs['aos-monsters-original.json']=[orig,'application/json'];outputs['aos-monsters-proposed.json']=[overlay(orig,s.proposal.records),'application/json'];outputs['aos-monsters-effective.json']=[effective,'application/json'];
 outputs['aos-normal-monster-balance.csv']=[normal.map(m=>flat(m,orig)),'text/csv'];outputs['aos-mvp-boss-balance.csv']=[boss.filter(m=>m.metadata?.tier!=='Abyss').map(m=>flat(m,orig)),'text/csv'];outputs['aos-abyss-boss-balance.csv']=[boss.filter(m=>m.metadata?.tier==='Abyss').map(m=>flat(m,orig)),'text/csv'];
 outputs['aos-monster-balance-overrides.json']=[{metadata:meta,overrides:s.custom},'application/json'];outputs['aos-boss-balance-overrides.json']=[{metadata:meta,overrides:Object.fromEntries(Object.entries(s.custom).filter(([id])=>active.find(m=>String(m.id)===id)?.boss))},'application/json'];
 outputs['aos-monster-reward-balance.csv']=[active.map(m=>({id:m.id,name:m.name,baseExp:m.rewards.baseExp,jobExp:m.rewards.jobExp,goldMin:m.rewards.goldMin,goldMax:m.rewards.goldMax})),'text/csv'];outputs['aos-player-power-curve.json']=[{metadata:meta,profiles:s.profiles},'application/json'];
 outputs['aos-ttk-simulation.csv']=[active.map(m=>({id:m.id,name:m.name,hp:m.stats.hp,dps:2000000,ttkSeconds:m.stats.hp/2000000,encounterSeconds:m.stats.hp/2000000+c.config.combatOverheadSeconds})),'text/csv'];outputs['aos-boss-ttk-comparison.csv']=[boss.flatMap(m=>[1,2,3,4,5].map(n=>({id:m.id,name:m.name,tier:m.metadata?.tier||'Abyss',hp:m.stats.hp,partySize:n,normalTtkSeconds:m.stats.hp/(n*2000000),highDpsTtkSeconds:m.stats.hp/(n*6000000)}))),'text/csv'];
 outputs['aos-map-farming-efficiency.csv']=[mapCsv(active),'text/csv'];outputs['aos-base-exp-table.csv']=[base,'text/csv'];outputs['aos-base-exp-table.json']=[{...meta,totalExp:c.base.totalExp,rows:base},'application/json'];
 for(const k of ['class1','class2']){outputs['aos-'+k+'-job-exp-table.csv']=[jobs(k),'text/csv'];outputs['aos-'+k+'-job-exp-table.json']=[{...meta,totalExp:c.jobs[k].totalExp,rows:jobs(k)},'application/json']}
 outputs['aos-player-progression-simulation.csv']=[c.scenarios,'text/csv'];outputs['aos-battlepass-progression.json']=[{...meta,durationDays:c.config.battlePassDays,seasons:c.config.seasons,scenarios:c.scenarios,roadmap:c.config.roadmap||[],status:'Proposed'},'application/json'];
 outputs['aos-progression-config.json']=[{...c.config,metadata:meta,maximumCombinedEfficiency:c.base.fastestEfficiency,maximumCompletionHours:c.base.fastestHours,totalBaseExp:c.base.totalExp,class1JobExp:c.jobs.class1.totalExp,class2JobExp:c.jobs.class2.totalExp},'application/json'];outputs['aos-balance-validation.json']=[{...meta,validation:c.validation},'application/json'];outputs['aos-balance-project.json']=[project,'application/json'];outputs['aos-balance-handoff.html']=[handoff(c,meta),'text/html'];
 const o=outputs[name];if(!o){dialog('Export unavailable','Output not registered.');return}download(name,o[1]==='text/csv'?csv(o[0]):JSON.stringify(o[0],null,2),o[1])
}
function overlay(d,records){const x=structuredClone(d);x.monsters=x.monsters.map(m=>{const p=records[String(m.id)];if(p)for(const g of ['stats','attributes','rewards','metadata'])if(p[g])m[g]={...(m[g]||{}),...p[g]};if(p.level!=null)m.level=p.level;if(p.metadata?.element)m.element=p.metadata.element;if(p.metadata?.aggro)m.aggro=p.metadata.aggro;if(p.metadata?.archetype)m.archetype=p.metadata.archetype;return m});return x}
function flat(m,src){const o=src.monsters.find(x=>String(x.id)===String(m.id));return{id:m.id,name:m.name,category:m.boss?(m.metadata?.tier==='Abyss'?'abyss':'mvp'):'normal',level:m.level,hpOriginal:o?.stats.hp,hpEffective:m.stats.hp,atkOriginal:o?.stats.atk,atkEffective:m.stats.atk,baseExpOriginal:o?.rewards.baseExp,baseExpEffective:m.rewards.baseExp,jobExpOriginal:o?.rewards.jobExp,jobExpEffective:m.rewards.jobExp,tier:m.metadata?.tier||'',sourceStatus:m.metadata?.status||'Original'}}
function mapCsv(ms){const a=new Map();for(const m of ms.filter(x=>!x.boss))for(const x of m.maps||[]){const v=a.get(x.name)||[];v.push(m);a.set(x.name,v)}return[...a].map(([map,rows])=>({map,monsterCount:rows.length,minLevel:Math.min(...rows.map(x=>x.level)),maxLevel:Math.max(...rows.map(x=>x.level)),weighting:'Equal time assumption',baseExpPerHour:rows.reduce((s,x)=>s+x.rewards.baseExp,0)/rows.length*30,jobExpPerHour:rows.reduce((s,x)=>s+x.rewards.jobExp,0)/rows.length*30}))}
function handoff(c,m){return'<!doctype html><meta charset="utf-8"><title>AOS Balance Handoff</title><h1>Age of Sylvanus — Balance Handoff</h1><p>Status: Draft · '+esc(m.versionName)+' · '+esc(m.versionId)+'</p><p>Base EXP '+fmt(c.base.totalExp,0)+' · Fastest modeled '+fmt(c.base.fastestHours,2)+'h · Content '+c.config.seasons+' seasons</p><table><tr><th>Status</th><th>Finding</th><th>Assumption</th></tr>'+c.validation.map(x=>'<tr><td>'+esc(x.status)+'</td><td>'+esc(x.message)+'</td><td>'+esc(x.assumption)+'</td></tr>').join('')+'</table><p>Modeled, not server-enforced. Open issues require playtest.</p>'}
window.addEventListener('resize',()=>store&&render());boot();
